"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1070],{11099:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PerkGuiController","desc":"Binds the Studio-authored `StarterGui.PerkGui` to `PerkClient`. Never builds\\nlayout: perk cards are clones of the authored `ExampleItem1` (unlocked) and\\n`ExampleItem3` (locked), active-perk rows clones of `ExampleActivePerk`. A\\nTopbarPlus icon (toggle key P) is the single source of truth for open/closed.\\n\\nThe list shows unlocked perks, locked perks the player is high enough to buy,\\nand locked perks at the next level milestone (the lowest `UnlockLevel` above\\nthe player\'s level) as a preview. Everything further out stays hidden.","realm":["Client"],"source":{"line":15,"path":"src/StarterPlayer/StarterPlayerScripts/PerkGuiController.client.luau"}}')}}]);